+import { $internal } from '../common';
+import { destroyEntity } from '../entity/entity';
+import type { Entity } from '../entity/types';
+import { allocateEntity, releaseEntity } from '../entity/utils/entity-index';
+import { isRelationPair } from '../relation/utils/is-relation';
+import { addTrait, getTrait, hasTrait, removeTrait } from '../trait/trait';
+import type { ConfigurableTrait, Trait, TraitRecord, ExtractSchema } from '../trait/types';
+import type { World } from '../world/types';
+
+type Command =
+    | { type: 'spawn'; entity: Entity }
+    | { type: 'destroy'; entity: Entity }
+    | { type: 'add'; entity: Entity; traits: ConfigurableTrait[]; exclusive: boolean }
+    | { type: 'remove'; entity: Entity; traits: (Trait | any)[] };
+
+export type DeferredWorld = {
+    spawn(...traits: ConfigurableTrait[]): Entity;
+    destroy(entity: Entity): void;
+    add(entity: Entity, ...traits: ConfigurableTrait[]): void;
+    remove(entity: Entity, ...traits: (Trait | any)[]): void;
+    addExclusive(entity: Entity, ...traits: ConfigurableTrait[]): void;
+    flush(): void;
+};
+
+type Buffer = { commands: Command[] };
+
+function active(world: World): Buffer {
+    const buffers = world[$internal].deferredBuffers;
+    return buffers[buffers.length - 1];
+}
+
+export function createDeferred(world: World): DeferredWorld {
+    return {
+        spawn(...traits) {
+            // Allocate an identity now, but leave it out of queries until its buffer is executed.
+            const entity = allocateEntity(world[$internal].entityIndex);
+            world[$internal].entityTraits.set(entity, new Set());
+            active(world).commands.push({ type: 'spawn', entity });
+            if (traits.length) active(world).commands.push({ type: 'add', entity, traits, exclusive: false });
+            return entity;
+        },
+        destroy(entity) {
+            active(world).commands.push({ type: 'destroy', entity });
+        },
+        add(entity, ...traits) {
+            active(world).commands.push({ type: 'add', entity, traits, exclusive: false });
+        },
+        remove(entity, ...traits) {
+            active(world).commands.push({ type: 'remove', entity, traits });
+        },
+        addExclusive(entity, ...traits) {
+            active(world).commands.push({ type: 'add', entity, traits, exclusive: true });
+        },
+        flush() {
+            flushBuffer(world, active(world));
+        },
+    };
+}
+
+export function beginDeferredScope(world: World) {
+    world[$internal].deferredBuffers.push({ commands: [] });
+}
+
+export function endDeferredScope(world: World) {
+    const buffer = active(world);
+    flushBuffer(world, buffer);
+    world[$internal].deferredBuffers.pop();
+}
+
+export function flushPendingForEntity(world: World, entity: Entity) {
+    if (world[$internal].isApplyingDeferred) return;
+    const buffers = world[$internal].deferredBuffers;
+    if (buffers.some((buffer) => buffer.commands.some((command) => command.entity === entity))) {
+        // Preserve FIFO ordering across scopes before an immediate entity mutation.
+        for (const buffer of buffers) flushBuffer(world, buffer);
+    }
+}
+
+export function deferredHas(world: World, entity: Entity, trait: Trait | any): boolean | undefined {
+    const commands = active(world).commands.filter((command) => command.entity === entity);
+    if (!commands.length) return undefined;
+    let value = isRelationPair(trait) ? entity.has(trait) : hasTrait(world, entity, trait);
+    for (const command of commands) {
+        if (command.type === 'destroy') return false;
+        if (command.type === 'remove' && command.traits.includes(trait)) value = false;
+        if (command.type === 'add') {
+            for (const config of command.traits) {
+                const item = Array.isArray(config) ? config[0] : config;
+                if (item === trait) value = true;
+                if (isRelationPair(item) && isRelationPair(trait)) {
+                    const a = item[$internal];
+                    const b = trait[$internal];
+                    if (a.relation === b.relation && (a.target === b.target || (command.exclusive && a.target !== '*'))) {
+                        value = a.target === b.target;
+                    }
+                }
+            }
+        }
+    }
+    return value;
+}
+
+export function deferredGet<T extends Trait>(world: World, entity: Entity, trait: T | any): TraitRecord<ExtractSchema<T>> | undefined {
+    const pending = active(world).commands.some((command) => command.entity === entity);
+    if (!pending) return undefined;
+    let result: any = getTrait(world, entity, trait);
+    for (const command of active(world).commands) {
+        if (command.entity !== entity) continue;
+        if (command.type === 'destroy') return undefined;
+        if (command.type === 'remove' && command.traits.includes(trait)) result = undefined;
+        if (command.type === 'add') {
+            for (const config of command.traits) {
+                const item = Array.isArray(config) ? config[0] : config;
+                const params = Array.isArray(config) ? config[1] : undefined;
+                if (item === trait) result = params ?? result ?? {};
+            }
+        }
+    }
+    return result;
+}
+
+function flushBuffer(world: World, buffer: Buffer) {
+    if (!buffer.commands.length || world[$internal].isApplyingDeferred) return;
+    const commands = buffer.commands;
+    buffer.commands = [];
+    const spawnedAndDestroyed = new Set<Entity>();
+    const spawned = new Set<Entity>();
+    for (const command of commands) {
+        if (command.type === 'spawn') spawned.add(command.entity);
+        else if (command.type === 'destroy' && spawned.has(command.entity)) spawnedAndDestroyed.add(command.entity);
+    }
+
+    world[$internal].isApplyingDeferred = true;
+    world[$internal].isDeferringEvents = true;
+    try {
+        for (const command of commands) {
+            if (spawnedAndDestroyed.has(command.entity)) continue;
+            if (command.type === 'spawn') continue;
+            if (!world.has(command.entity)) continue;
+            if (command.type === 'destroy') {
+                if (command.entity === world[$internal].worldEntity) {
+                    throw new Error('Koota: The world entity cannot be destroyed with deferred commands.');
+                }
+                destroyEntity(world, command.entity);
+            } else if (command.type === 'remove') {
+                removeTrait(world, command.entity, ...command.traits);
+            } else {
+                if (command.exclusive) {
+                    for (const config of command.traits) {
+                        const pair = Array.isArray(config) ? config[0] : config;
+                        if (isRelationPair(pair)) removeTrait(world, command.entity, pair[$internal].relation('*'));
+                    }
+                }
+                addTrait(world, command.entity, ...command.traits);
+            }
+        }
+        for (const entity of spawnedAndDestroyed) {
+            world[$internal].entityTraits.delete(entity);
+            releaseEntity(world[$internal].entityIndex, entity);
+        }
+    } finally {
+        world[$internal].isApplyingDeferred = false;
+        world[$internal].isDeferringEvents = false;
+        flushDeferredEvents(world);
+    }
+}
+
+export function emitDeferredEvent(world: World, subscriptions: Set<any>, type: 'add' | 'remove' | 'change', entity: Entity, target?: Entity) {
+    if (!world[$internal].isDeferringEvents) {
+        for (const sub of subscriptions) sub(entity, target);
+        return;
+    }
+    let events = world[$internal].deferredEvents.get(subscriptions);
+    if (!events) world[$internal].deferredEvents.set(subscriptions, (events = new Map()));
+    const key = `${entity}:${target ?? ''}`;
+    const previous = events.get(key);
+    if ((previous === 'add' && type === 'remove') || (previous === 'remove' && type === 'add')) events.delete(key);
+    else if (type !== 'change' || !previous) events.set(key, type);
+}
+
+function flushDeferredEvents(world: World) {
+    for (const [subscriptions, events] of world[$internal].deferredEvents) {
+        for (const [key, type] of events) {
+            const [entity, target] = key.split(':');
+            for (const sub of subscriptions) sub(Number(entity), target === '' ? undefined : Number(target));
+        }
+    }
+    world[$internal].deferredEvents.clear();
+}
